def _paeth(a, b, c):
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    return b if pb <= pc else c


def _decode_png_rgba(data):
    import struct
    import zlib

    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a PNG")
    pos = 8
    ihdr = None
    idat = bytearray()
    while pos + 8 <= len(data):
        length = struct.unpack(">I", data[pos:pos + 4])[0]
        kind = data[pos + 4:pos + 8]
        body = data[pos + 8:pos + 8 + length]
        if kind == b"IHDR":
            ihdr = struct.unpack(">IIBBBBB", body)
        elif kind == b"IDAT":
            idat += body
        elif kind == b"IEND":
            break
        pos += 12 + length
    if ihdr is None:
        raise ValueError("no IHDR")
    width, height, depth, color, _comp, _filt, interlace = ihdr
    if depth != 8 or interlace != 0:
        raise ValueError("unsupported depth/interlace")
    channels = {0: 1, 2: 3, 4: 2, 6: 4}.get(color)
    if channels is None:
        raise ValueError("unsupported colour type %d" % color)

    raw = zlib.decompress(bytes(idat))
    stride = width * channels
    out = bytearray(height * stride)
    prev = bytearray(stride)
    src = 0
    for y in range(height):
        ft = raw[src]
        src += 1
        line = bytearray(raw[src:src + stride])
        src += stride
        if ft == 1:
            for i in range(channels, stride):
                line[i] = (line[i] + line[i - channels]) & 0xFF
        elif ft == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 0xFF
        elif ft == 3:
            for i in range(stride):
                a = line[i - channels] if i >= channels else 0
                line[i] = (line[i] + ((a + prev[i]) >> 1)) & 0xFF
        elif ft == 4:
            for i in range(stride):
                a = line[i - channels] if i >= channels else 0
                c = prev[i - channels] if i >= channels else 0
                line[i] = (line[i] + _paeth(a, prev[i], c)) & 0xFF
        elif ft != 0:
            raise ValueError("unknown filter %d" % ft)
        out[y * stride:(y + 1) * stride] = line
        prev = line

    rgba = bytearray(width * height * 4)
    for i in range(width * height):
        o = i * channels
        if channels == 4:
            rgba[i * 4:i * 4 + 4] = out[o:o + 4]
        elif channels == 3:
            rgba[i * 4:i * 4 + 3] = out[o:o + 3]
            rgba[i * 4 + 3] = 255
        elif channels == 2:
            g, a = out[o], out[o + 1]
            rgba[i * 4:i * 4 + 4] = bytes((g, g, g, a))
        else:
            g = out[o]
            rgba[i * 4:i * 4 + 4] = bytes((g, g, g, 255))
    return width, height, rgba


def _composite_rgba(width, height, rgba, bg_rgb):
    br, bg_, bb = bg_rgb
    rows = []
    for y in range(height):
        row = []
        base = y * width * 4
        for x in range(width):
            o = base + x * 4
            a = rgba[o + 3] / 255.0
            row.append("#%02x%02x%02x" % (
                int(round(rgba[o] * a + br * (1.0 - a))),
                int(round(rgba[o + 1] * a + bg_ * (1.0 - a))),
                int(round(rgba[o + 2] * a + bb * (1.0 - a)))))
        rows.append(row)
    return rows


def _hex_rgb(hex_color):
    hex_color = str(hex_color).lstrip("#")
    return tuple(int(hex_color[i:i + 2], 16) for i in (0, 2, 4))


def photoimage(tk_module, size=None):
    if size is None:
        return tk_module.PhotoImage(data=LOGO_PNG_B64)
    key = ("pil", size)
    if _HAVE_PIL:
        if key not in _CACHE:
            img = _Image.open(io.BytesIO(_LOGO_BYTES)).convert("RGBA")
            if img.width != size:
                img = img.resize((size, size), _Image.LANCZOS)
            buf = io.BytesIO()
            img.save(buf, format="PNG")
            _CACHE[key] = buf.getvalue()
        return tk_module.PhotoImage(data=base64.b64encode(_CACHE[key]).decode("ascii"))
    img = tk_module.PhotoImage(data=LOGO_PNG_B64)
    if size and img.width() > size:
        factor = max(1, round(img.width() / size))
        if factor > 1:
            img = img.subsample(factor)
    return img


def surface_image(tk_module, size, hex_bg):
    key = (size, str(hex_bg))
    if key not in _SURF_CACHE:
        if _HAVE_PIL:
            base = _Image.new("RGBA", (size, size),
                              _hex_rgb(hex_bg) + (255,))
            fg = _Image.open(io.BytesIO(_LOGO_BYTES)).convert("RGBA")
            if fg.width != size:
                fg = fg.resize((size, size), _Image.LANCZOS)
            base.alpha_composite(fg)
            buf = io.BytesIO()
            base.convert("RGB").save(buf, format="PNG")
            _SURF_CACHE[key] = buf.getvalue()
        else:
            _SURF_CACHE[key] = None
    if _SURF_CACHE[key] is not None:
        return tk_module.PhotoImage(data=base64.b64encode(_SURF_CACHE[key]).decode("ascii"))

    # Pure-Python path: PNG decode + per-pixel composite run ONCE per
    # (size, background); the row data is cached and only the (cheap)
    # PhotoImage creation + put repeats per call.
    img = tk_module.PhotoImage(width=size, height=size)
    try:
        rows = _SURF_ROWS.get(key)
        if rows is None:
            raw = base64.b64decode(LOGO_PNG_B64)
            w, h, rgba = _decode_png_rgba(raw)
            if (w, h) != (size, size):
                rs = bytearray(size * size * 4)
                for y in range(size):
                    sy = min(h - 1, y * h // size)
                    for x in range(size):
                        sx = min(w - 1, x * w // size)
                        o = (sy * w + sx) * 4
                        d = (y * size + x) * 4
                        rs[d:d + 4] = rgba[o:o + 4]
                w, h, rgba = size, size, rs
            rows = _composite_rgba(w, h, rgba, _hex_rgb(hex_bg))
            _SURF_ROWS[key] = rows
        img.put(rows, (0, 0))
    except Exception:
        try:
            img = tk_module.PhotoImage(data=LOGO_PNG_B64)
        except Exception:
            pass
    return img


def ico_path():
    global _ICO_PATH
    if _ICO_PATH is None:
        import atexit
        import os
        import tempfile
        fd, path = tempfile.mkstemp(suffix=".ico", prefix="snappyai-")
        with os.fdopen(fd, "wb") as fh:
            fh.write(base64.b64decode(ICO_B64))
        _ICO_PATH = path

        def _cleanup(p=path):
            try:
                os.remove(p)
            except OSError:
                pass
        atexit.register(_cleanup)
    return _ICO_PATH



